@router.post("/search/collections/{collection_id}/reindex")
def trigger_collection_reindex(
    collection_id: str,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    collection = db.query(SearchCollection).filter(
        SearchCollection.id == collection_id,
        SearchCollection.account_id == user.account_id
    ).first()
    if not collection:
        raise HTTPException(status_code=404, detail="Search collection not found")

    reindex_opensearch_collection.apply_async(args=[collection_id])
    return {"status": "reindexing", "collection_id": collection_id}
